function libriFatal(err){
 console.error('Libri Presentes fatal error:',err);
 try{
  const target=document.querySelector('#app');
  if(target&&!target.innerHTML.trim()){
   const msg=err&&err.message?String(err.message):String(err||'Erro desconhecido');
   target.innerHTML='<section style="min-height:100vh;display:grid;place-items:center;padding:24px;background:#f7f3ee;color:#292622;font-family:system-ui,sans-serif"><div style="max-width:520px;text-align:center"><h1 style="font-family:Georgia,serif;font-weight:400">Nao conseguimos abrir o Libri Presentes.</h1><p style="line-height:1.6;color:#756d66">A pagina carregou, mas o aplicativo encontrou um erro.</p><code style="display:block;white-space:pre-wrap;word-break:break-word;background:#fff;padding:12px;border-radius:12px;margin-top:14px">'+esc(msg)+'</code></div></section>';
  }
 }catch(_){}
}

async function boot(){
 const path=location.pathname.replace(/\/+$/,'')||'/';
 if(path==='/')return libriLanding();
 if(path==='/admin')return libriAdminPage();
 let m=path.match(/^\/c\/([^/]+)$/);if(m)return libriClientPage(decodeURIComponent(m[1]));
 m=path.match(/^\/e\/([^/]+)$/);if(m)return libriPublicPage(decodeURIComponent(m[1]),null);
 m=path.match(/^\/preview\/([^/]+)\/([^/]+)$/);if(m)return libriPublicPage(decodeURIComponent(m[1]),decodeURIComponent(m[2]));
 m=path.match(/^\/r\/([^/]+)$/);if(m)return libriReservationPage(decodeURIComponent(m[1]));
 libriState('link','P\u00e1gina n\u00e3o encontrada','Confira o endere\u00e7o recebido e tente novamente.');
}

function libriLanding(){
 app.innerHTML=`<section class="state"><div class="state-card"><i class="ti ti-gift"></i><div class="kicker">LIBRI CONVITES</div><h1>Libri Presentes</h1><p>Desejos, cotas e experi\u00eancias em uma p\u00e1gina feita para parecer celebra\u00e7\u00e3o, n\u00e3o cat\u00e1logo.</p></div></section>`;
}
function libriState(icon,title,text,action=''){
 app.innerHTML=`<section class="state"><div class="state-card"><i class="ti ti-${attr(icon)}"></i><h1>${esc(title)}</h1><p>${esc(text)}</p>${action}</div></section>`;
}
function libriLoading(text='Preparando\u2026'){libriState('loader-2','',text)}
function libriToast(text){toastEl.textContent=text;toastEl.classList.add('show');clearTimeout(libriToast.t);libriToast.t=setTimeout(()=>toastEl.classList.remove('show'),2000)}
function money(c){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format((Number(c)||0)/100)}
function percent(a,b){return b?Math.max(0,Math.min(100,Math.round(Number(a)/Number(b)*100))):0}
function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
function attr(v){return esc(v).replaceAll('`','&#096;')}
function js(v){return attr(JSON.stringify(String(v)))}
function api(path,opt={}){return fetch(path,opt).then(async r=>({r,data:await r.json().catch(()=>({}))}))}
function setTheme(e){const s=document.documentElement.style;s.setProperty('--primary',e.primary_color||'#6f6258');s.setProperty('--secondary',e.secondary_color||'#d8cec4');s.setProperty('--accent',e.accent_color||'#a8ad96');s.setProperty('--bg',e.background_color||'#f7f3ee');s.setProperty('--text',e.text_color||'#292622');document.querySelector('meta[name="theme-color"]')?.setAttribute('content',e.background_color||'#f7f3ee');document.title=`${e.event_name} | Libri Presentes`}
function topbar(label,actions=''){return `<div class="top"><div class="wrap top-inner"><div class="brand"><span class="brand-mark"><i class="ti ti-gift"></i></span><span>${esc(label)}</span></div><div class="actions">${actions}</div></div></div>`}
function datePt(v){if(!v)return'';const d=new Date(`${v}T12:00:00`);return Number.isNaN(d.getTime())?'':new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric'}).format(d)}
function statusLabel(s){return({configuring:'Em configura\u00e7\u00e3o',ready:'Pronto para publicar',active:'Ativo',inactive:'Desativado'})[s]||'Em configura\u00e7\u00e3o'}
function statusBadge(s){return s==='active'?'ok':s==='ready'?'info':s==='inactive'?'danger':'warn'}
function typeLabel(t){return({quota:'Cota compartilhada',creative:'Cota criativa',experience:'Experi\u00eancia',physical:'Presente f\u00edsico'})[t]||'Desejo'}
function eventTypeLabel(t){return({wedding:'Casamento',bridal_shower:'Ch\u00e1 de panela',housewarming:'Casa nova',engagement:'Noivado',other:'Celebra\u00e7\u00e3o'})[t]||'Celebra\u00e7\u00e3o'}
function categoryIcon(cat){const c=String(cat||'').toLowerCase();if(c.includes('cozinha'))return'tools-kitchen-2';if(c.includes('sala'))return'sofa';if(c.includes('quarto'))return'bed';if(c.includes('banheiro'))return'bath';if(c.includes('lavander'))return'washing-machine';if(c.includes('lua')||c.includes('viagem'))return'plane';if(c.includes('exper'))return'stars';if(c.includes('criativ'))return'sparkles';if(c.includes('casa'))return'home';return'gift'}

/* PUBLIC */
async function libriPublicPage(slug,previewToken){
 libriLoading('Abrindo esta hist\u00f3ria\u2026');
 const path=previewToken?`/api/previews/${encodeURIComponent(slug)}/${encodeURIComponent(previewToken)}`:`/api/events/${encodeURIComponent(slug)}`;
 const {r,data}=await api(path);
 if(!r.ok){
  if(r.status===409)return libriState(data.display_status==='inactive'?'lock':'sparkles',data.display_status==='inactive'?'Lista encerrada':'Estamos preparando esta lista',data.message||'Ela ainda n\u00e3o foi publicada.');
  if(r.status===403)return libriState('lock','Pr\u00e9via expirada','Pe\u00e7a um novo link de pr\u00e9via.');
  return libriState('search','Evento n\u00e3o encontrado','Confira o link recebido e tente novamente.');
 }
 publicState={event:data.event,gifts:data.gifts||[],category:'Todos',price:'Todos',isPreview:Boolean(data.is_preview)};
 setTheme(data.event);libriRenderPublic();
}
function libriRenderPublic(){
 const e=publicState.event,g=publicState.gifts,total=g.reduce((s,x)=>s+Number(x.target_cents||0),0),confirmed=g.reduce((s,x)=>s+Number(x.confirmed_cents||0),0),p=percent(confirmed,total);
 const cats=['Todos',...new Set(g.map(x=>x.category).filter(Boolean))];
 app.innerHTML=`<div class="public style-${attr(e.experience_style||'home')}">${publicState.isPreview?'<div class="public-preview-ribbon"><i class="ti ti-eye"></i> PR\u00c9VIA PRIVADA \u00b7 a\u00e7\u00f5es desativadas</div>':''}<section class="public-hero"><div class="wrap public-hero-inner"><div class="public-brand"><i class="ti ti-gift"></i> LIBRI PRESENTES</div><div class="hero-stage"><div class="hero-copy"><div class="kicker">${esc(e.public_title||eventTypeLabel(e.event_type))}</div><h1>${esc(e.event_name)}</h1><p>${esc(e.intro||'Escolha um desejo e participe desta nova fase do seu jeito.')}</p>${e.event_date?`<div class="hero-date"><i class="ti ti-calendar-heart"></i>${esc(datePt(e.event_date))}</div>`:''}<div class="hero-actions"><button class="btn" onclick="document.querySelector('#desejos').scrollIntoView({behavior:'smooth'})"><i class="ti ti-heart"></i> Conhecer nossos desejos</button></div></div>${libriStoryVisual(e.experience_style,p,e.event_name)}</div><div class="scroll-cue"><span>Uma hist\u00f3ria constru\u00edda por quem faz parte dela</span><i class="ti ti-arrow-down"></i></div></div></section>
 ${libriStoryBoard(p,cats.filter(x=>x!=='Todos').slice(0,4))}
 <section class="public-section wrap" id="desejos"><div class="section-head"><div><div class="kicker">ESCOLHA DO SEU JEITO</div><h2>Desejos com hist\u00f3ria.</h2></div><p>Nada de loja obrigat\u00f3ria. Voc\u00ea pode contribuir com uma cota, viver uma experi\u00eancia junto com o casal ou comprar um presente f\u00edsico onde preferir.</p></div><div class="filters" id="catFilters">${cats.map(c=>`<button class="filter ${publicState.category===c?'active':''}" onclick="libriSetCategory(${js(c)})">${esc(c)}</button>`).join('')}</div><div class="filters" id="priceFilters">${priceFiltersHtml()}</div><div class="wish-stream" id="wishStream">${publicWishCards()}</div></section><footer class="public-footer wrap">Feito com <b>Libri Presentes</b> \u00b7 o valor do Pix vai direto para o casal</footer></div>`;
}
function libriStoryVisual(style,p,name){
 if(style==='journey')return `<div class="story-visual"><div class="journey-art"><div class="journey-line"></div><span class="journey-stop"><i class="ti ti-home-heart"></i></span><span class="journey-stop"><i class="ti ti-heart"></i></span><span class="journey-stop"><i class="ti ti-plane"></i></span><span class="journey-heart"><i class="ti ti-route-heart"></i></span></div><div class="visual-label">NOSSA JORNADA \u00b7 ${p}% REALIZADO</div></div>`;
 if(style==='classic'){const initials=String(name||'L P').split(/\s+&?\s*/).filter(Boolean).slice(0,2).map(x=>x[0]).join('');return `<div class="story-visual"><div class="classic-art"><div class="classic-frame"><div class="classic-monogram">${esc(initials||'LP')}</div><div class="classic-stars"><i class="ti ti-sparkles"></i><i class="ti ti-heart"></i><i class="ti ti-star"></i></div></div></div><div class="visual-label">NOSSA CELEBRA\u00c7\u00c3O \u00b7 ${p}% REALIZADO</div></div>`}
 const stage=Math.min(5,Math.floor(p/20)+1);
 return `<div class="story-visual stage-${stage}"><svg class="house-svg" viewBox="0 0 520 430" aria-hidden="true"><path class="soft" d="M95 194 260 62l165 132v173H95z"/><path class="line" d="M65 205 260 48l195 157M95 194v173h330V194"/><rect class="line" x="225" y="258" width="70" height="109" rx="34"/><rect class="line" x="130" y="225" width="62" height="58" rx="10"/><rect class="line" x="329" y="225" width="62" height="58" rx="10"/><g class="detail s1"><circle class="accent" cx="175" cy="334" r="18"/><path class="line" d="M175 317v-28m0 9-13-13m13 5 15-15"/></g><g class="detail s2"><path class="soft" d="M315 322h73v32h-73z"/><path class="line" d="M323 322v-22m57 22v-22"/></g><g class="detail s3"><ellipse class="soft" cx="149" cy="329" rx="42" ry="17"/><path class="line" d="M128 329v27m42-27v27"/><circle class="accent" cx="140" cy="318" r="7"/><circle class="accent" cx="158" cy="318" r="7"/></g><g class="detail s4"><path class="line" d="M367 105c18 12 31 31 33 53"/><path class="line" d="M353 118c18 11 27 27 28 44"/><circle class="accent" cx="402" cy="163" r="5"/></g><g class="detail s5"><path class="line" d="M213 168c29 21 65 21 94 0"/><circle class="accent" cx="230" cy="179" r="6"/><circle class="accent" cx="260" cy="185" r="6"/><circle class="accent" cx="290" cy="179" r="6"/></g></svg><div class="visual-label">NOSSO LAR \u00b7 ${p}% REALIZADO</div></div>`;
}
function libriStoryBoard(p,cats){
 const list=cats.length?cats:['Cozinha','Sala','Quarto','Lua de Mel'];
 return `<section class="public-section wrap"><div class="section-head"><div><div class="kicker">CADA PRESENTE MUDA A CENA</div><h2>A hist\u00f3ria ganha forma.</h2></div><p>O progresso s\u00f3 muda quando o casal confirma que a contribui\u00e7\u00e3o realmente chegou. Sem progresso de faz de conta.</p></div><div class="story-board"><div class="story-main"><i class="ti ti-home-heart"></i><div><div class="overall-number">${p}<small>% realizado</small></div><h3>Um novo cap\u00edtulo</h3><p>Cada confirma\u00e7\u00e3o acende mais um detalhe desta hist\u00f3ria, do primeiro caf\u00e9 \u00e0 viagem que ainda vai virar lembran\u00e7a.</p></div></div><div class="chapter-grid">${list.slice(0,4).map(c=>chapterCard(c)).join('')}</div></div></section>`;
}
function chapterCard(cat){const a=publicState.gifts.filter(g=>g.category===cat),t=a.reduce((s,g)=>s+Number(g.target_cents||0),0),c=a.reduce((s,g)=>s+Number(g.confirmed_cents||0),0),p=percent(c,t);return `<button class="chapter" style="--p:${p}%" onclick="libriSetCategory(${js(cat)});document.querySelector('#desejos').scrollIntoView({behavior:'smooth'})"><i class="ti ti-${categoryIcon(cat)}"></i><h4>${esc(cat)}</h4><span>${a.length?`${a.length} desejo${a.length===1?'':'s'} \u00b7 ${p}% realizado`:'Um espa\u00e7o para novos desejos'}</span></button>`}
function priceFiltersHtml(){return [['Todos','Todos os valores'],['100','At\u00e9 R$100'],['250','R$101\u2013250'],['500','R$251\u2013500'],['plus','Acima de R$500']].map(([v,l])=>`<button class="filter ${publicState.price===v?'active':''}" onclick="libriSetPrice(${js(v)})">${l}</button>`).join('')}
function libriSetCategory(c){publicState.category=c;document.querySelector('#catFilters').innerHTML=['Todos',...new Set(publicState.gifts.map(x=>x.category).filter(Boolean))].map(x=>`<button class="filter ${publicState.category===x?'active':''}" onclick="libriSetCategory(${js(x)})">${esc(x)}</button>`).join('');document.querySelector('#wishStream').innerHTML=publicWishCards()}
function libriSetPrice(p){publicState.price=p;document.querySelector('#priceFilters').innerHTML=priceFiltersHtml();document.querySelector('#wishStream').innerHTML=publicWishCards()}
function filteredWishes(){return publicState.gifts.filter(g=>{if(publicState.category!=='Todos'&&g.category!==publicState.category)return false;const v=Number(g.target_cents||0);if(publicState.price==='100'&&v>10000)return false;if(publicState.price==='250'&&(v<=10000||v>25000))return false;if(publicState.price==='500'&&(v<=25000||v>50000))return false;if(publicState.price==='plus'&&v<=50000)return false;return true})}
function publicWishCards(){const arr=filteredWishes();return arr.length?arr.map(publicWishCard).join(''):`<div class="empty">Nenhum desejo nessa sele\u00e7\u00e3o. Tente outra faixa ou categoria.</div>`}
function publicWishCard(g){
 const pixDone=Number(g.target_cents)>0&&Number(g.confirmed_cents)>=Number(g.target_cents),physicalDone=g.gift_type==='physical'&&Number(g.received_reservations||0)>=Number(g.quantity||1),reserved=g.gift_type==='physical'&&Number(g.active_reservations||0)>=Number(g.quantity||1),done=pixDone||physicalDone,extra=publicState.event.completed_behavior==='allow_extra',locked=(done&&!extra)||(reserved&&!done),p=percent(g.confirmed_cents,g.target_cents);
 return `<article class="wish"><div class="wish-media">${g.image_url?`<img src="${attr(g.image_url)}" alt="">`:`<i class="ti ti-${attr(g.icon_name||'gift')}"></i>`}<span class="wish-type">${esc(typeLabel(g.gift_type))}</span></div><div class="wish-content"><div class="kicker">${esc(g.category||'Um desejo')}</div><h3>${esc(g.title)}</h3>${g.description?`<p>${esc(g.description)}</p>`:''}${g.preferred_color?`<span class="pref">Prefer\u00eancia: ${esc(g.preferred_color)}</span>`:''}<div class="wish-value"><span>Valor de refer\u00eancia</span><strong>${money(g.target_cents)}</strong></div>${g.gift_type!=='physical'?`<div class="progress"><span style="width:${p}%"></span></div><div class="wish-stats"><span>${money(g.confirmed_cents)} confirmados</span><span>${Number(g.contributor_count||0)} participa${Number(g.contributor_count||0)===1?'\u00e7\u00e3o':'\u00e7\u00f5es'}</span></div>`:`<div class="wish-stats"><span>${done?'Recebido \u2713':reserved?'Reservado por um convidado':'Dispon\u00edvel'}</span><span>Compra livre</span></div>`}<button class="btn ${locked?'secondary':''}" ${locked?'disabled':''} onclick="libriOpenWish(${js(g.id)})">${done?'Desejo realizado \u2713':reserved?'Reservado':'Quero presentear'}</button></div></article>`;
}
function libriOpenWish(id){
 const g=publicState.gifts.find(x=>x.id===id);if(!g)return;
 if(publicState.isPreview)return libriModal(`<div class="modal-head"><div><div class="kicker">PR\u00c9VIA PRIVADA</div><h2>${esc(g.title)}</h2><p class="muted small">Aqui o convidado escolher\u00e1 como quer presentear. As transa\u00e7\u00f5es ficam desligadas durante a pr\u00e9via.</p></div><button class="close" onclick="libriCloseModal()">\u00d7</button></div><div class="option-grid"><div class="option"><i class="ti ti-qrcode"></i><b>Contribuir via Pix</b><span>Pix contextual direto para o casal.</span></div>${g.gift_type==='physical'?'<div class="option"><i class="ti ti-shopping-bag"></i><b>Comprar onde quiser</b><span>Reserva tempor\u00e1ria e confirma\u00e7\u00e3o de compra.</span></div>':''}</div>`);
 const physical=g.gift_type==='physical'&&g.allow_physical;
 libriModal(`<div class="modal-head"><div><div class="kicker">${esc(typeLabel(g.gift_type))}</div><h2>${esc(g.title)}</h2><p class="muted small">${esc(g.description||'Escolha a forma que funciona melhor para voc\u00ea.')}</p></div><button class="close" onclick="libriCloseModal()">\u00d7</button></div>${physical?`<div class="option-grid"><button class="option" onclick="libriPixStep(${js(id)})"><i class="ti ti-qrcode"></i><b>Dar o valor via Pix</b><span>O dinheiro vai direto para o casal. A Libri n\u00e3o recebe nem cobra sobre o presente.</span></button><button class="option" onclick="libriReserveStep(${js(id)})"><i class="ti ti-shopping-bag"></i><b>Vou comprar o presente</b><span>Reserve e compre em qualquer loja. A prefer\u00eancia \u00e9 apenas uma refer\u00eancia.</span></button></div>`:`<div class="option-grid"><button class="option" onclick="libriPixStep(${js(id)})"><i class="ti ti-heart-dollar"></i><b>Participar deste desejo</b><span>Escolha seu valor e envie direto para o Pix do casal.</span></button></div>`}<div id="giftStep"></div>`);
}
function smartAmounts(remaining){const r=Math.max(100,Number(remaining)||100);const raw=r<=10000?[r*.25,r*.5,r]:[r*.1,r*.25,r*.5,r];return [...new Set(raw.map(v=>Math.max(100,Math.round(v/1000)*1000)).filter(v=>v<=r))].slice(0,4)}
function libriPixStep(id){const g=publicState.gifts.find(x=>x.id===id),remaining=Math.max(100,Number(g.target_cents)-Number(g.confirmed_cents||0)),presets=smartAmounts(remaining);document.querySelector('#giftStep').innerHTML=`<div class="stack" style="margin-top:16px"><div class="field"><label>QUANTO VOC\u00ca QUER PRESENTEAR?</label><div class="preset-row">${presets.map(v=>`<button class="preset" onclick="document.querySelector('#amount').value=${Math.round(v/100)}">${money(v)}</button>`).join('')}</div><input id="amount" type="number" min="1" value="${Math.max(1,Math.round(presets[0]/100))}"></div><div class="form-grid"><div class="field"><label>SEU NOME</label><input id="guestName" placeholder="Como o casal reconhecer\u00e1 voc\u00ea?"></div><div class="field"><label>WHATSAPP OU E-MAIL</label><input id="guestContact" placeholder="Seu contato"></div><div class="field full"><label>RECADO OPCIONAL</label><textarea id="guestMessage" placeholder="Um carinho para acompanhar o presente."></textarea></div></div><button class="btn wide" onclick="libriShowPix(${js(id)})">Continuar para o Pix</button></div>`}
function libriShowPix(id){const e=publicState.event,g=publicState.gifts.find(x=>x.id===id),name=document.querySelector('#guestName').value.trim(),contact=document.querySelector('#guestContact').value.trim(),message=document.querySelector('#guestMessage').value.trim(),amount=Math.round(Number(document.querySelector('#amount').value)*100);if(!name||!contact||!amount)return libriToast('Preencha nome, contato e valor.');if(!e.pix_key||!e.pix_holder_name||!e.pix_city)return libriToast('O casal ainda n\u00e3o configurou o Pix.');const payload=buildPix(e.pix_key,e.pix_holder_name,e.pix_city,amount/100);window.libriPendingPix={id,name,contact,message,amount};document.querySelector('#giftStep').innerHTML=`<div class="pix-card"><div class="kicker">VOC\u00ca EST\u00c1 PRESENTEANDO</div><h3>${money(amount)}</h3><p class="small muted">${esc(g.title)}</p><div class="bank-note"><i class="ti ti-lock"></i> Pix direto para ${esc(e.pix_holder_name)}</div><div class="qr" id="pixQr"></div><div class="copyline"><code id="pixCode">${esc(payload)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#pixCode').textContent)">Copiar Pix</button></div><p class="small muted">Depois do pagamento, avise ao casal. O progresso s\u00f3 muda quando eles confirmarem o recebimento.</p><button class="btn ok wide" onclick="libriDeclarePix()"><i class="ti ti-check"></i> J\u00e1 fiz meu Pix</button></div>`;renderQr('pixQr',payload)}
async function libriDeclarePix(){const p=window.libriPendingPix;if(!p)return;const {r,data}=await api(`/api/events/${encodeURIComponent(publicState.event.slug)}/contributions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({gift_id:p.id,guest_name:p.name,guest_contact:p.contact,guest_message:p.message,amount_cents:p.amount})});if(!r.ok){if(data.max_cents)document.querySelector('#amount')?.setAttribute('value',Math.round(data.max_cents/100));return libriToast(data.message||'N\u00e3o foi poss\u00edvel registrar.')}libriCloseModal();libriToast('Presente enviado para confirma\u00e7\u00e3o do casal \u2713');await libriPublicPage(publicState.event.slug,null)}
function libriReserveStep(id){document.querySelector('#giftStep').innerHTML=`<div class="stack" style="margin-top:16px"><div class="form-grid"><div class="field"><label>SEU NOME</label><input id="resName"></div><div class="field"><label>WHATSAPP OU E-MAIL</label><input id="resContact"></div></div><p class="small muted">O presente fica reservado por ${Number(publicState.event.reservation_hours||48)} horas. Se a compra n\u00e3o for confirmada, ele volta automaticamente para a lista.</p><button class="btn wide" onclick="libriReserveWish(${js(id)})">Reservar presente</button></div>`}
async function libriReserveWish(id){const name=document.querySelector('#resName').value.trim(),contact=document.querySelector('#resContact').value.trim();if(!name||!contact)return libriToast('Informe nome e contato.');const {r,data}=await api(`/api/events/${encodeURIComponent(publicState.event.slug)}/reservations`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({gift_id:id,guest_name:name,guest_contact:contact})});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel reservar.');document.querySelector('#giftStep').innerHTML=`<div class="pix-card"><i class="ti ti-heart-check" style="font-size:38px;color:var(--primary)"></i><h3>Guardamos para voc\u00ea.</h3><p class="small muted">Salve seu link pessoal. \u00c9 nele que voc\u00ea confirma quando realmente comprar o presente.</p><div class="copyline"><code id="manageUrl">${esc(data.manage_url)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#manageUrl').textContent)">Copiar</button></div><a class="btn wide" style="margin-top:10px" href="${attr(data.manage_url)}">Abrir meu presente</a></div>`}

/* RESERVATION */
async function libriReservationPage(token){libriLoading();const {r,data}=await api(`/api/reservations/${encodeURIComponent(token)}`);if(!r.ok)return libriState('search','Reserva n\u00e3o encontrada','Este link pode ter expirado ou sido cancelado.');const x=data.reservation;app.innerHTML=`${topbar('MEU PRESENTE')}<div class="state" style="min-height:calc(100dvh - 64px)"><div class="state-card"><i class="ti ti-shopping-bag"></i><div class="kicker">${esc(x.event_name)}</div><h1>${esc(x.gift_title)}</h1><p>Status: <b>${esc(resLabel(x.status))}</b>${x.preferred_color?` \u00b7 prefer\u00eancia ${esc(x.preferred_color)}`:''}</p>${x.status==='reserved'?`<button class="btn wide" onclick="libriReservationAction(${js(token)},'purchased')">J\u00e1 comprei este presente</button><button class="btn secondary wide" style="margin-top:8px" onclick="libriReservationAction(${js(token)},'cancel')">N\u00e3o vou mais comprar</button>`:x.status==='purchased'?`<p>Compra informada ao casal. Quando eles receberem, marcam o presente como recebido. \ud83e\udd0d</p><button class="btn secondary wide" onclick="libriReservationAction(${js(token)},'cancel')">Cancelar reserva</button>`:`<a class="btn secondary wide" href="/e/${attr(x.slug)}">Voltar \u00e0 lista</a>`}</div></div>`}
async function libriReservationAction(token,action){const {r,data}=await api(`/api/reservations/${encodeURIComponent(token)}/${action}`,{method:'POST'});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel alterar.');libriReservationPage(token)}
function resLabel(s){return({reserved:'Reservado',purchased:'Compra informada',received:'Recebido',expired:'Reserva expirada',cancelled:'Cancelado'})[s]||s}

/* CLIENT */
async function libriClientPage(token){sessionStorage.setItem('libriClientToken',token);libriLoading('Abrindo seu espa\u00e7o\u2026');await refreshClient()}
async function refreshClient(){const token=sessionStorage.getItem('libriClientToken');const {r,data}=await api('/api/client/dashboard',{headers:{'x-client-token':token}});if(!r.ok)return libriState('lock','Acesso inv\u00e1lido','Este link de administra\u00e7\u00e3o n\u00e3o \u00e9 mais v\u00e1lido.');clientState=data;setTheme(data.event);if(!Number(data.event.onboarding_completed||0))return renderOnboarding();renderClient(clientTab)}
function clientHeader(){return topbar('LIBRI PRESENTES',`<a class="btn secondary small" href="${attr(clientState.event.private_preview_url)}" target="_blank"><i class="ti ti-eye"></i> Ver pr\u00e9via</a>`)}
function renderOnboarding(){const e=clientState.event;app.innerHTML=`<div class="onboarding"><div class="wrap"><div class="onboard-top"><div class="brand"><span class="brand-mark"><i class="ti ti-gift"></i></span>LIBRI PRESENTES</div><span class="badge">Configura\u00e7\u00e3o inicial</span></div><div class="onboard-card"><div class="steps">${[1,2,3,4].map(n=>`<span class="step-dot ${n<onboardingStep?'done':n===onboardingStep?'active':''}"></span>`).join('')}</div>${onboardingContent(e)}</div></div></div>`}
function onboardingContent(e){
 if(onboardingStep===1)return `<div class="kicker">PASSO 1 DE 4 \u00b7 SUA HIST\u00d3RIA</div><h1>Primeiro, quem estamos celebrando?</h1><p>O nome e a mensagem aparecem na p\u00e1gina dos convidados. Nada precisa soar como texto de loja.</p><div class="form-grid"><div class="field full"><label>NOME DO CASAL / EVENTO</label><input id="obName" value="${attr(e.event_name||'')}"></div><div class="field"><label>DATA</label><input id="obDate" type="date" value="${attr(e.event_date||'')}"></div><div class="field full"><label>MENSAGEM DE BOAS-VINDAS</label><textarea id="obIntro">${esc(e.intro||'')}</textarea></div></div><button class="btn wide" style="margin-top:14px" onclick="onboardingNext1()">Continuar</button>`;
 if(onboardingStep===2)return `<div class="kicker">PASSO 2 DE 4 \u00b7 PIX DIRETO</div><h1>O presente vai para voc\u00ea.</h1><p>A Libri n\u00e3o recebe nem desconta nada do valor. O convidado paga direto na sua chave e voc\u00ea confirma o recebimento depois.</p><div class="form-grid"><div class="field full"><label>CHAVE PIX</label><input id="obPix" value="${attr(e.pix_key||'')}"></div><div class="field"><label>TIPO DA CHAVE</label><select id="obPixType">${pixTypeOptions(e.pix_key_type)}</select></div><div class="field"><label>NOME DO TITULAR</label><input id="obHolder" value="${attr(e.pix_holder_name||'')}"></div><div class="field"><label>CIDADE DO TITULAR</label><input id="obCity" value="${attr(e.pix_city||'')}" placeholder="Ex.: GOIANIA"></div></div><div class="actions" style="margin-top:14px"><button class="btn secondary" onclick="onboardingBack()">Voltar</button><button class="btn" onclick="onboardingNext2()">Continuar</button></div>`;
 if(onboardingStep===3)return `<div class="kicker">PASSO 3 DE 4 \u00b7 EXPERI\u00caNCIA</div><h1>Qual \u00e9 a cara dessa lista?</h1><p>O conte\u00fado \u00e9 o mesmo, mas a narrativa muda. Voc\u00ea pode trocar isso depois.</p><div class="choice-grid"><button class="choice ${e.experience_style==='home'?'active':''}" onclick="chooseOnboardStyle('home')"><i class="ti ti-home-heart"></i><b>Nosso Lar</b><span>A casa vai ganhando detalhes conforme os presentes s\u00e3o confirmados.</span></button><button class="choice ${e.experience_style==='journey'?'active':''}" onclick="chooseOnboardStyle('journey')"><i class="ti ti-route"></i><b>Nossa Jornada</b><span>Os desejos viram paradas de uma hist\u00f3ria que continua depois da festa.</span></button><button class="choice ${e.experience_style==='classic'?'active':''}" onclick="chooseOnboardStyle('classic')"><i class="ti ti-sparkles"></i><b>Cl\u00e1ssica</b><span>Mais editorial e elegante, sem perder a leveza do Libri.</span></button></div><div class="actions" style="margin-top:14px"><button class="btn secondary" onclick="onboardingBack()">Voltar</button><button class="btn" onclick="onboardingNext3()">Continuar</button></div>`;
 return `<div class="kicker">PASSO 4 DE 4 \u00b7 PONTO DE PARTIDA</div><h1>Quer come\u00e7ar de onde?</h1><p>As listas prontas entram sem valores. Voc\u00ea decide quanto cada desejo vale antes de publicar.</p><div class="option-grid"><button class="option" onclick="finishOnboarding('blank')"><i class="ti ti-pencil"></i><b>Come\u00e7ar do zero</b><span>Crie cada desejo do seu jeito.</span></button><button class="option" onclick="finishOnboarding('balanced')"><i class="ti ti-scale"></i><b>Lista equilibrada</b><span>Cotas, casa, experi\u00eancias e um pouco de humor.</span></button><button class="option" onclick="finishOnboarding('money')"><i class="ti ti-heart-dollar"></i><b>Mais cotas</b><span>Menos objetos e mais liberdade para usar o presente.</span></button><button class="option" onclick="finishOnboarding('home')"><i class="ti ti-home"></i><b>Foco no novo lar</b><span>Uma base forte de itens e objetivos para a casa.</span></button><button class="option" onclick="finishOnboarding('honeymoon')"><i class="ti ti-plane"></i><b>Lua de mel</b><span>Experi\u00eancias, refei\u00e7\u00f5es e pedacinhos da viagem.</span></button></div><div class="actions" style="margin-top:14px"><button class="btn secondary" onclick="onboardingBack()">Voltar</button></div>`;
}
function pixTypeOptions(current){return [['random','Aleat\u00f3ria'],['cpf','CPF'],['cnpj','CNPJ'],['email','E-mail'],['phone','Telefone']].map(([v,l])=>`<option value="${v}" ${current===v?'selected':''}>${l}</option>`).join('')}
async function clientPatch(body){const token=sessionStorage.getItem('libriClientToken');return api('/api/client/event',{method:'PATCH',headers:{'content-type':'application/json','x-client-token':token},body:JSON.stringify(body)})}
async function onboardingNext1(){const name=document.querySelector('#obName').value.trim();if(!name)return libriToast('Informe o nome do evento.');const {r,data}=await clientPatch({event_name:name,event_date:document.querySelector('#obDate').value,intro:document.querySelector('#obIntro').value.trim()});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel salvar.');clientState.event.event_name=name;clientState.event.event_date=document.querySelector('#obDate').value;clientState.event.intro=document.querySelector('#obIntro').value.trim();onboardingStep=2;renderOnboarding()}
async function onboardingNext2(){const pix=document.querySelector('#obPix').value.trim(),holder=document.querySelector('#obHolder').value.trim(),city=document.querySelector('#obCity').value.trim();if(!pix||!holder||!city)return libriToast('Preencha chave, titular e cidade do Pix.');const body={pix_key:pix,pix_key_type:document.querySelector('#obPixType').value,pix_holder_name:holder,pix_city:city};const {r,data}=await clientPatch(body);if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel salvar.');Object.assign(clientState.event,body);onboardingStep=3;renderOnboarding()}
async function chooseOnboardStyle(style){clientState.event.experience_style=style;renderOnboarding()}
async function onboardingNext3(){const {r,data}=await clientPatch({experience_style:clientState.event.experience_style});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel salvar.');onboardingStep=4;renderOnboarding()}
function onboardingBack(){onboardingStep=Math.max(1,onboardingStep-1);renderOnboarding()}
async function finishOnboarding(mode){const token=sessionStorage.getItem('libriClientToken');if(mode!=='blank'){const gifts=(STARTER_MODES[mode]||[]).map(i=>TEMPLATES[i]);const x=await api('/api/client/gifts/bulk',{method:'POST',headers:{'content-type':'application/json','x-client-token':token},body:JSON.stringify({gifts})});if(!x.r.ok)return libriToast(x.data.message||'N\u00e3o foi poss\u00edvel montar a lista.')}const y=await clientPatch({onboarding_completed:true});if(!y.r.ok)return libriToast(y.data.message||'N\u00e3o foi poss\u00edvel concluir.');clientTab='overview';await refreshClient();libriToast(mode==='blank'?'Tudo pronto para come\u00e7ar \u2728':'Sua base est\u00e1 pronta. Agora defina os valores \u2728')}

function renderClient(tab='overview'){clientTab=tab;const e=clientState.event,c=clientState.contributions,r=clientState.reservations,g=clientState.gifts,confirmed=c.filter(x=>x.status==='confirmed').reduce((s,x)=>s+Number(x.amount_cents),0),pending=c.filter(x=>x.status==='pending').length,inProgress=r.filter(x=>['reserved','purchased'].includes(x.status)).length;app.innerHTML=`<div class="app-shell">${clientHeader()}<div class="wrap app-content"><div class="page-title"><div><div class="kicker">${esc(eventTypeLabel(e.event_type))}</div><h1>${esc(e.event_name)}</h1></div><span class="badge ${statusBadge(e.display_status)}"><i class="ti ti-${e.display_status==='active'?'world-check':e.display_status==='ready'?'circle-check':'settings'}"></i>${statusLabel(e.display_status)}</span></div><div class="tabs">${clientTabButton('overview','Vis\u00e3o geral',tab)}${clientTabButton('wishes','Desejos',tab)}${clientTabButton('received','Recebidos',tab)}${clientTabButton('page','Minha p\u00e1gina',tab)}${clientTabButton('settings','Configura\u00e7\u00f5es',tab)}</div><div id="clientTab">${clientTabContent(tab,{confirmed,pending,inProgress,gifts:g.length})}</div></div></div>`;if(tab==='page')renderShareQr()}
function clientTabButton(id,label,active){return `<button class="tab ${active===id?'active':''}" onclick="renderClient(${js(id)})">${label}</button>`}
function clientTabContent(tab,stats){const e=clientState.event;
 if(tab==='overview')return `<div class="stat-grid"><div class="stat"><strong>${money(stats.confirmed)}</strong><span>Pix confirmados por voc\u00ea</span></div><div class="stat"><strong>${stats.pending}</strong><span>Pix aguardando confer\u00eancia</span></div><div class="stat"><strong>${stats.inProgress}</strong><span>presentes f\u00edsicos em andamento</span></div><div class="stat"><strong>${stats.gifts}</strong><span>desejos cadastrados</span></div></div><div class="panel-grid"><div class="panel"><div class="spread"><h2>${e.display_status==='active'?'Sua lista est\u00e1 no ar':e.display_status==='ready'?'Tudo pronto para publicar':'Antes de publicar'}</h2><span class="badge ${statusBadge(e.display_status)}">${statusLabel(e.display_status)}</span></div>${readinessHtml(e.readiness)}${e.display_status==='ready'||e.display_status==='inactive'?`<button class="btn ok wide" style="margin-top:12px" onclick="publishClientEvent()"><i class="ti ti-rocket"></i> ${e.display_status==='inactive'?'Publicar novamente':'Publicar minha lista'}</button>`:e.display_status==='active'?`<a class="btn secondary wide" style="margin-top:12px" href="${attr(e.public_url)}" target="_blank"><i class="ti ti-external-link"></i> Abrir p\u00e1gina p\u00fablica</a>`:''}</div><div class="panel"><h2>Precisa da sua aten\u00e7\u00e3o</h2><div class="list">${clientPendingRows(true)||'<div class="empty">Nada pendente. A casinha est\u00e1 em paz. \u2728</div>'}</div></div></div>`;
 if(tab==='wishes')return `<div class="panel-grid"><div class="panel"><div class="spread"><h2>Seus desejos</h2><button class="btn small" onclick="openGiftEditor()"><i class="ti ti-plus"></i> Novo desejo</button></div><p class="small muted">Desejos sem valor ficam guardados no painel, mas n\u00e3o aparecem para convidados.</p><div class="list">${clientState.gifts.map(clientGiftRow).join('')||'<div class="empty">Sua lista ainda est\u00e1 vazia.</div>'}</div></div><div class="panel"><div class="spread"><h2>Biblioteca Libri</h2><span class="badge">edit\u00e1vel</span></div><div class="library-toolbar"><input id="templateSearch" placeholder="Buscar uma ideia\u2026" oninput="renderTemplateLibrary(this.value)"></div><div class="template-grid" id="templateGrid">${templateLibraryHtml('')}</div></div></div>`;
 if(tab==='received')return `<div class="panel-grid"><div class="panel"><h2>Pix informados</h2><p class="small muted">\u201cJ\u00e1 fiz meu Pix\u201d n\u00e3o muda o progresso. Voc\u00ea confere no seu banco e confirma aqui.</p><div class="list">${clientPendingRows(false)||'<div class="empty">Nenhuma contribui\u00e7\u00e3o ainda.</div>'}</div></div><div class="panel"><h2>Presentes f\u00edsicos</h2><p class="small muted">Reservado, compra informada e recebido s\u00e3o tr\u00eas estados diferentes.</p><div class="list">${clientReservationRows()||'<div class="empty">Nenhuma reserva f\u00edsica ainda.</div>'}</div></div></div>`;
 if(tab==='page')return `<div class="panel-grid"><div class="share-card"><div class="kicker">SUA P\u00c1GINA</div><h2>${esc(e.event_name)}</h2><p>${e.display_status==='active'?'Este \u00e9 o endere\u00e7o que voc\u00ea envia aos convidados.':'Use a pr\u00e9via privada para conferir tudo antes de publicar.'}</p><div class="actions"><a class="btn" href="${attr(e.private_preview_url)}" target="_blank"><i class="ti ti-eye"></i> Abrir pr\u00e9via</a>${e.display_status==='active'?`<a class="btn secondary" href="${attr(e.public_url)}" target="_blank"><i class="ti ti-world"></i> Abrir p\u00fablica</a>`:''}</div><div class="copyline" style="margin-top:14px"><code id="publicUrl">${esc(e.public_url)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#publicUrl').textContent)">Copiar</button></div><button class="btn secondary wide" style="margin-top:9px" onclick="shareWhatsApp()"><i class="ti ti-brand-whatsapp"></i> Compartilhar pelo WhatsApp</button></div><div class="panel"><h2>QR Code da lista</h2><div class="qr" id="shareQr"></div><p class="small muted center">O endere\u00e7o \u00e9 o mesmo antes e depois da publica\u00e7\u00e3o. Antes de ativar, o convidado v\u00ea apenas que a lista est\u00e1 sendo preparada.</p><button class="btn secondary wide" onclick="downloadQr()">Baixar QR</button></div></div>`;
 return `<div class="panel-grid"><div class="panel"><h2>Evento e Pix</h2><div class="form-grid"><div class="field full"><label>NOME DO EVENTO</label><input id="ceName" value="${attr(e.event_name)}"></div><div class="field"><label>DATA</label><input id="ceDate" type="date" value="${attr(e.event_date||'')}"></div><div class="field"><label>ESTILO DA P\u00c1GINA</label><select id="ceStyle"><option value="home" ${e.experience_style==='home'?'selected':''}>Nosso Lar</option><option value="journey" ${e.experience_style==='journey'?'selected':''}>Nossa Jornada</option><option value="classic" ${e.experience_style==='classic'?'selected':''}>Cl\u00e1ssica</option></select></div><div class="field full"><label>MENSAGEM DE BOAS-VINDAS</label><textarea id="ceIntro">${esc(e.intro||'')}</textarea></div><div class="field"><label>CHAVE PIX</label><input id="cePix" value="${attr(e.pix_key||'')}"></div><div class="field"><label>TIPO</label><select id="cePixType">${pixTypeOptions(e.pix_key_type)}</select></div><div class="field"><label>NOME DO TITULAR</label><input id="ceHolder" value="${attr(e.pix_holder_name||'')}"></div><div class="field"><label>CIDADE DO TITULAR</label><input id="ceCity" value="${attr(e.pix_city||'')}"></div><div class="field"><label>AO COMPLETAR UM DESEJO</label><select id="ceComplete"><option value="show" ${e.completed_behavior==='show'?'selected':''}>Mostrar como realizado</option><option value="hide" ${e.completed_behavior==='hide'?'selected':''}>Ocultar da lista</option><option value="allow_extra" ${e.completed_behavior==='allow_extra'?'selected':''}>Continuar aceitando</option></select></div><div class="field"><label>RESERVA DE PRESENTE F\u00cdSICO</label><select id="ceHours"><option value="24" ${Number(e.reservation_hours)===24?'selected':''}>24 horas</option><option value="48" ${Number(e.reservation_hours)===48?'selected':''}>48 horas</option><option value="72" ${Number(e.reservation_hours)===72?'selected':''}>72 horas</option></select></div><div class="field full"><label>TEXTO AO COMPARTILHAR</label><textarea id="ceShare">${esc(e.share_description||`Criamos nossa lista de presentes na Libri. Vem conhecer nossos desejos \ud83e\udd0d`)}</textarea></div></div><button class="btn wide" style="margin-top:12px" onclick="saveClientSettings()">Salvar altera\u00e7\u00f5es</button></div><div class="panel"><h2>Publica\u00e7\u00e3o</h2><p class="small muted">Desativar tira a lista do ar sem perder seus dados. Excluir apaga evento, desejos, registros e m\u00eddias definitivamente.</p>${e.display_status==='active'?`<button class="btn warn wide" onclick="deactivateClientEvent()">Desativar lista</button>`:`<button class="btn ok wide" onclick="publishClientEvent()">${e.display_status==='inactive'?'Publicar novamente':'Publicar lista'}</button>`}<div class="panel danger-zone" style="margin-top:14px"><h2>Excluir evento</h2><div class="field"><label>DIGITE EXATAMENTE: ${esc(e.event_name)}</label><input id="deleteConfirm"></div><button class="btn danger wide" style="margin-top:9px" onclick="deleteClientEvent()">Excluir definitivamente</button></div></div></div>`;
}
function readinessHtml(r){if(r?.ready)return `<div class="check ok"><i class="ti ti-circle-check"></i><span>Nome, Pix e pelo menos um desejo com valor est\u00e3o prontos.</span></div>`;return `<div class="readiness">${(r?.missing||[]).map(x=>`<div class="check missing"><i class="ti ti-circle-dashed"></i><span>${esc(x)}</span></div>`).join('')}</div>`}
function clientGiftRow(g){const incomplete=Number(g.target_cents)<100;return `<div class="list-row"><div class="row-icon"><i class="ti ti-${attr(g.icon_name||'gift')}"></i></div><div class="row-main"><b>${esc(g.title)}</b><small>${esc(typeLabel(g.gift_type))} \u00b7 ${incomplete?'valor ainda n\u00e3o definido':money(g.target_cents)}${!incomplete?` \u00b7 ${percent(g.confirmed_cents,g.target_cents)}% realizado`:''}</small></div>${incomplete?'<span class="badge warn">Falta valor</span>':''}<button class="btn secondary small" onclick="openGiftEditor(${js(g.id)})"><i class="ti ti-pencil"></i></button><button class="btn secondary small" onclick="deleteGift(${js(g.id)})"><i class="ti ti-trash"></i></button></div>`}
function clientPendingRows(onlyPending){const arr=clientState.contributions.filter(c=>!onlyPending||c.status==='pending');return arr.map(c=>`<div class="list-row"><div class="row-icon"><i class="ti ti-${attr(c.icon_name||'gift')}"></i></div><div class="row-main"><b>${esc(c.guest_name)} \u00b7 ${money(c.amount_cents)}</b><small>${esc(c.gift_title)} \u00b7 ${esc(c.guest_contact)}${c.guest_message?` \u00b7 \u201c${esc(c.guest_message)}\u201d`:''}</small></div><span class="badge ${c.status==='confirmed'?'ok':c.status==='rejected'?'danger':'warn'}">${c.status==='confirmed'?'Confirmado':c.status==='rejected'?'Recusado':'Aguardando'}</span>${c.status==='pending'?`<button class="btn ok small" onclick="setContribution(${js(c.id)},'confirm')"><i class="ti ti-check"></i></button><button class="btn secondary small" onclick="setContribution(${js(c.id)},'reject')"><i class="ti ti-x"></i></button>`:''}</div>`).join('')}
function clientReservationRows(){return clientState.reservations.map(r=>`<div class="list-row"><div class="row-icon"><i class="ti ti-${attr(r.icon_name||'gift')}"></i></div><div class="row-main"><b>${esc(r.guest_name)} \u00b7 ${esc(r.gift_title)}</b><small>${esc(r.guest_contact)} \u00b7 ${resLabel(r.status)}</small></div><span class="badge ${r.status==='received'?'ok':r.status==='expired'||r.status==='cancelled'?'danger':'warn'}">${resLabel(r.status)}</span>${['reserved','purchased'].includes(r.status)?`<button class="btn ok small" onclick="setReservation(${js(r.id)},'received')">Recebi</button><button class="btn secondary small" onclick="setReservation(${js(r.id)},'cancel')"><i class="ti ti-x"></i></button>`:''}</div>`).join('')}
function templateLibraryHtml(q){const term=String(q||'').trim().toLowerCase(),items=TEMPLATES.map((t,i)=>({...t,i})).filter(t=>!term||`${t.title} ${t.category} ${t.description}`.toLowerCase().includes(term));return items.map(t=>`<button class="template" onclick="openGiftEditor(null,${t.i})"><span class="template-cat">${esc(t.category)}</span><i class="ti ti-${attr(t.icon_name)}"></i><b>${esc(t.title)}</b><small>Defina o valor e ajuste o texto do seu jeito.</small></button>`).join('')||'<div class="empty">Nenhuma ideia encontrada.</div>'}
function renderTemplateLibrary(q){document.querySelector('#templateGrid').innerHTML=templateLibraryHtml(q)}
function openGiftEditor(id=null,templateIndex=null){const g=id?clientState.gifts.find(x=>x.id===id):templateIndex!==null?TEMPLATES[templateIndex]:{title:'',description:'',category:'',gift_type:'quota',target_cents:0,quantity:1,icon_name:'gift',preferred_color:'',allow_pix:1};selectedIcon=g.icon_name||'gift';pendingGiftPhoto=null;libriModal(`<div class="modal-head"><div><div class="kicker">${id?'EDITAR DESEJO':'NOVO DESEJO'}</div><h2>${id?'Ajuste como quiser.':'O que voc\u00eas desejam?'}</h2><p class="small muted">Voc\u00ea pode salvar sem valor e decidir depois. S\u00f3 desejos com valor aparecem para convidados.</p></div><button class="close" onclick="libriCloseModal()">\u00d7</button></div><div class="form-grid" style="margin-top:14px"><div class="field full"><label>NOME DO DESEJO</label><input id="geTitle" value="${attr(g.title||'')}"></div><div class="field"><label>TIPO</label><select id="geType"><option value="quota">Cota compartilhada</option><option value="creative">Cota criativa</option><option value="experience">Experi\u00eancia</option><option value="physical">Presente f\u00edsico</option></select></div><div class="field"><label>CATEGORIA / AMBIENTE</label><input id="geCat" value="${attr(g.category||'')}" placeholder="Cozinha, Lua de Mel\u2026"></div><div class="field"><label>VALOR DE REFER\u00caNCIA</label><input id="geValue" type="number" min="0" value="${Number(g.target_cents)?Math.round(Number(g.target_cents)/100):''}" placeholder="Defina quando quiser"></div><div class="field"><label>COR / PREFER\u00caNCIA</label><input id="geColor" value="${attr(g.preferred_color||'')}" placeholder="Opcional"></div><div class="field full"><label>DESCRI\u00c7\u00c3O</label><textarea id="geDesc">${esc(g.description||'')}</textarea></div><div class="field full"><label>\u00cdCONE</label><div class="icon-grid">${ICONS.map(i=>`<button class="icon-btn ${i===selectedIcon?'active':''}" title="${attr(i)}" onclick="pickGiftIcon(${js(i)})"><i class="ti ti-${attr(i)}"></i></button>`).join('')}</div></div><div class="field full"><label>FOTO OPCIONAL</label><input id="gePhoto" type="file" accept="image/jpeg,image/png,image/webp"><span class="small muted" id="photoInfo">${g.image_url?'J\u00e1 existe uma foto. Se escolher outra, ela ser\u00e1 substitu\u00edda.':'Sem foto? O \u00edcone assume e a p\u00e1gina continua bonita.'}</span></div></div><button class="btn wide" style="margin-top:12px" onclick="saveGift(${js(id||'')})">${id?'Salvar desejo':'Adicionar \u00e0 lista'}</button>`);document.querySelector('#geType').value=g.gift_type||'quota';bindGiftPhoto()}
function pickGiftIcon(i){selectedIcon=i;document.querySelectorAll('.icon-btn').forEach(b=>b.classList.toggle('active',b.title===i))}
function bindGiftPhoto(){const f=document.querySelector('#gePhoto');if(!f)return;f.addEventListener('change',async()=>{if(!f.files[0])return;try{pendingGiftPhoto=await compressImage(f.files[0],760,85000,.82);document.querySelector('#photoInfo').textContent=`Otimizada para ${Math.round(pendingGiftPhoto.size/1024)} KB antes de enviar.`}catch{libriToast('N\u00e3o foi poss\u00edvel processar essa imagem.') }})}
async function saveGift(id){const token=sessionStorage.getItem('libriClientToken'),value=Number(document.querySelector('#geValue').value||0),body={title:document.querySelector('#geTitle').value.trim(),gift_type:document.querySelector('#geType').value,category:document.querySelector('#geCat').value.trim(),target_cents:Math.round(value*100),preferred_color:document.querySelector('#geColor').value.trim(),description:document.querySelector('#geDesc').value.trim(),icon_name:selectedIcon,allow_pix:true};if(!body.title)return libriToast('D\u00ea um nome ao desejo.');const path=id?`/api/client/gifts/${id}`:'/api/client/gifts',method=id?'PATCH':'POST';const {r,data}=await api(path,{method,headers:{'content-type':'application/json','x-client-token':token},body:JSON.stringify(body)});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel salvar.');const giftId=id||data.gift_id;if(pendingGiftPhoto){const up=await fetch(`/api/client/gifts/${giftId}/image`,{method:'PUT',headers:{'x-client-token':token,'content-type':'image/webp'},body:pendingGiftPhoto});if(!up.ok)return libriToast('O desejo foi salvo, mas a foto n\u00e3o subiu.');pendingGiftPhoto=null}libriCloseModal();clientTab='wishes';await refreshClient();libriToast('Desejo salvo \u2713')}
async function deleteGift(id){if(!confirm('Excluir este desejo? Contribui\u00e7\u00f5es e reservas ligadas a ele tamb\u00e9m ser\u00e3o removidas.'))return;const token=sessionStorage.getItem('libriClientToken'),{r,data}=await api(`/api/client/gifts/${id}`,{method:'DELETE',headers:{'x-client-token':token}});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel excluir.');await refreshClient();renderClient('wishes')}
async function setContribution(id,action){const token=sessionStorage.getItem('libriClientToken'),{r,data}=await api(`/api/client/contributions/${id}/${action}`,{method:'POST',headers:{'x-client-token':token}});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel alterar.');clientTab='received';await refreshClient();libriToast(action==='confirm'?'Recebimento confirmado \u2713':'Contribui\u00e7\u00e3o recusada')}
async function setReservation(id,action){const token=sessionStorage.getItem('libriClientToken'),{r,data}=await api(`/api/client/reservations/${id}/${action}`,{method:'POST',headers:{'x-client-token':token}});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel alterar.');clientTab='received';await refreshClient()}
async function publishClientEvent(){const token=sessionStorage.getItem('libriClientToken'),{r,data}=await api('/api/client/publish',{method:'POST',headers:{'x-client-token':token}});if(!r.ok){libriToast(data.message||'A lista ainda n\u00e3o est\u00e1 pronta.');return}clientTab='overview';await refreshClient();libriToast('Sua lista est\u00e1 no ar \u2728')}
async function deactivateClientEvent(){if(!confirm('Desativar a lista p\u00fablica agora? Voc\u00ea pode publicar novamente depois.'))return;const token=sessionStorage.getItem('libriClientToken'),{r,data}=await api('/api/client/deactivate',{method:'POST',headers:{'x-client-token':token}});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel desativar.');clientTab='settings';await refreshClient();libriToast('Lista desativada')}
async function saveClientSettings(){const body={event_name:document.querySelector('#ceName').value.trim(),event_date:document.querySelector('#ceDate').value,intro:document.querySelector('#ceIntro').value.trim(),experience_style:document.querySelector('#ceStyle').value,pix_key:document.querySelector('#cePix').value.trim(),pix_key_type:document.querySelector('#cePixType').value,pix_holder_name:document.querySelector('#ceHolder').value.trim(),pix_city:document.querySelector('#ceCity').value.trim(),reservation_hours:Number(document.querySelector('#ceHours').value),completed_behavior:document.querySelector('#ceComplete').value,share_description:document.querySelector('#ceShare').value.trim()};const {r,data}=await clientPatch(body);if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel salvar.');clientTab='settings';await refreshClient();libriToast('Configura\u00e7\u00f5es salvas \u2713')}
async function deleteClientEvent(){const text=document.querySelector('#deleteConfirm').value;if(text!==clientState.event.event_name)return libriToast('O nome digitado n\u00e3o confere.');if(!confirm('Isso apaga o evento, desejos, contribui\u00e7\u00f5es, reservas e m\u00eddias. Continuar?'))return;const token=sessionStorage.getItem('libriClientToken'),{r,data}=await api('/api/client/event',{method:'DELETE',headers:{'content-type':'application/json','x-client-token':token},body:JSON.stringify({confirm:text})});if(!r.ok)return libriToast(data.message||'N\u00e3o foi poss\u00edvel excluir.');sessionStorage.removeItem('libriClientToken');libriState('trash','Evento exclu\u00eddo','Os dados deste evento foram removidos.')}
function renderShareQr(){renderQr('shareQr',clientState.event.public_url)}
function shareWhatsApp(){const e=clientState.event,text=`${e.share_description||`Criamos nossa lista de presentes na Libri. Vem conhecer nossos desejos \ud83e\udd0d`}\n${e.public_url}`;window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener')}
function downloadQr(){const canvas=document.querySelector('#shareQr canvas');if(!canvas)return libriToast('QR ainda n\u00e3o est\u00e1 pronto.');const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download=`qr-${clientState.event.slug}.png`;a.click()}

/* ADMIN */
async function libriAdminPage(){const key=sessionStorage.getItem('libriAdminKey');if(!key)return adminLogin();libriLoading('Abrindo \u00c1rea Libri\u2026');const {r,data}=await api('/api/admin/events',{headers:{'x-admin-key':key}});if(!r.ok){sessionStorage.removeItem('libriAdminKey');return adminLogin('Chave inv\u00e1lida.')}adminEvents=data.events||[];renderAdmin()}
function adminLogin(error=''){app.innerHTML=`<section class="state"><div class="state-card"><i class="ti ti-lock"></i><div class="kicker">\u00c1REA LIBRI</div><h1>Entrar</h1><p>${error?esc(error):'Cria\u00e7\u00e3o, identidade e gest\u00e3o das p\u00e1ginas Libri Presentes.'}</p><div class="field"><input id="adminKey" type="password" placeholder="Chave da \u00c1rea Libri" onkeydown="if(event.key==='Enter')saveAdminKey()"></div><button class="btn wide" style="margin-top:10px" onclick="saveAdminKey()">Entrar</button></div></section>`}
function saveAdminKey(){const k=document.querySelector('#adminKey').value.trim();if(!k)return libriToast('Digite a chave.');sessionStorage.setItem('libriAdminKey',k);libriAdminPage()}
function renderAdmin(){app.innerHTML=`<div class="app-shell">${topbar('\u00c1REA LIBRI',`<button class="btn small" onclick="openEventCreator()"><i class="ti ti-plus"></i> Novo evento</button>`)}<div class="wrap app-content"><div class="admin-hero"><div><div class="kicker">LIBRI PRESENTES</div><h2>Eventos que viram experi\u00eancias.</h2></div><p class="small muted">A cliente cuida dos desejos. A Libri cuida da identidade, acesso e qualidade da p\u00e1gina.</p></div><div class="event-grid">${adminEvents.map(adminEventCard).join('')||'<div class="empty">Nenhum evento ainda. Crie o primeiro.</div>'}</div></div></div>`}
function adminEventCard(e){return `<article class="event-card"><div class="spread"><span class="badge ${statusBadge(e.display_status)}">${statusLabel(e.display_status)}</span><span class="small muted">${esc(eventTypeLabel(e.event_type))}</span></div><div><h3>${esc(e.event_name)}</h3><div class="event-meta"><span><i class="ti ti-link"></i> /${esc(e.slug)}</span>${e.event_date?`<span><i class="ti ti-calendar"></i> ${esc(datePt(e.event_date))}</span>`:''}<span><i class="ti ti-gift"></i> ${Number(e.gift_count||0)} desejos</span></div></div><div class="event-footer"><span class="small muted">${Number(e.pending_count||0)} aguardando confirma\u00e7\u00e3o \u00b7 ${money(e.confirmed_cents)} confirmados</span><button class="btn secondary small" onclick="openAdminEvent(${js(e.id)})">Gerenciar</button></div></article>`}
function openEventCreator(){libriModal(`<div class="modal-head"><div><div class="kicker">NOVO EVENTO</div><h2>Crie a base, n\u00e3o a lista.</h2><p class="small muted">A cliente recebe um acesso pr\u00f3prio para cadastrar desejos e Pix. Voc\u00ea controla identidade, preview e publica\u00e7\u00e3o visual.</p></div><button class="close" onclick="libriCloseModal()">\u00d7</button></div><div class="form-grid" style="margin-top:14px"><div class="field full"><label>NOME DO CASAL / EVENTO</label><input id="aeName" placeholder="Ana & Pedro"></div><div class="field"><label>NOME DA CLIENTE</label><input id="aeClient"></div><div class="field"><label>SLUG</label><input id="aeSlug" placeholder="ana-e-pedro"></div><div class="field"><label>TIPO</label><select id="aeType"><option value="wedding">Casamento</option><option value="bridal_shower">Ch\u00e1 de panela</option><option value="housewarming">Casa nova</option><option value="engagement">Noivado</option><option value="other">Outro</option></select></div><div class="field"><label>DATA</label><input id="aeDate" type="date"></div><div class="field"><label>ESTILO INICIAL</label><select id="aeStyle"><option value="home">Nosso Lar</option><option value="journey">Nossa Jornada</option><option value="classic">Cl\u00e1ssica</option></select></div><div class="field full"><label>T\u00cdTULO EDITORIAL</label><input id="aeTitle" value="Nossa lista de desejos"></div><div class="field full"><label>MENSAGEM INICIAL</label><textarea id="aeIntro">Estamos construindo uma nova fase e reunimos alguns desejos para ela. Escolha um deles e participe do seu jeito.</textarea></div><div class="field full"><label>PALETA</label><div class="color-row"><div class="color-field"><span class="tiny muted">Principal</span><input id="aePrimary" type="color" value="#6F6258"></div><div class="color-field"><span class="tiny muted">Secund\u00e1ria</span><input id="aeSecondary" type="color" value="#D8CEC4"></div><div class="color-field"><span class="tiny muted">Acento</span><input id="aeAccent" type="color" value="#A8AD96"></div></div></div></div><button id="libriCreateEventBtn" class="btn wide" style="margin-top:12px" onclick="libriCreateEvent()">Criar evento</button>`)}
async function libriCreateEvent(){const btn=document.querySelector('#libriCreateEventBtn'),name=document.querySelector('#aeName').value.trim();if(!name)return libriToast('Informe o nome do evento.');const body={event_name:name,client_name:document.querySelector('#aeClient').value.trim(),slug:document.querySelector('#aeSlug').value.trim(),event_type:document.querySelector('#aeType').value,event_date:document.querySelector('#aeDate').value,experience_style:document.querySelector('#aeStyle').value,public_title:document.querySelector('#aeTitle').value.trim(),intro:document.querySelector('#aeIntro').value.trim(),primary_color:document.querySelector('#aePrimary').value,secondary_color:document.querySelector('#aeSecondary').value,accent_color:document.querySelector('#aeAccent').value};btn.disabled=true;btn.textContent='Criando\u2026';try{const key=sessionStorage.getItem('libriAdminKey'),{r,data}=await api('/api/admin/events',{method:'POST',headers:{'content-type':'application/json','x-admin-key':key},body:JSON.stringify(body)});if(!r.ok){btn.disabled=false;btn.textContent='Criar evento';return libriToast(data.message||'N\u00e3o foi poss\u00edvel criar.')}libriModal(`<div class="modal-head"><div><div class="kicker">EVENTO CRIADO</div><h2>Agora existem tr\u00eas portas.</h2><p class="small muted">O painel da cliente \u00e9 privado. A pr\u00e9via funciona antes da publica\u00e7\u00e3o. O link p\u00fablico s\u00f3 libera a experi\u00eancia quando tudo estiver pronto.</p></div><button class="close" onclick="libriCloseModal();libriAdminPage()">\u00d7</button></div><div class="stack"><div class="field"><label>ACESSO DA CLIENTE</label><div class="copyline"><code id="newClientUrl">${esc(data.client_url)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#newClientUrl').textContent)">Copiar</button></div></div><div class="field"><label>PR\u00c9VIA PRIVADA</label><div class="copyline"><code id="newPreviewUrl">${esc(data.preview_url)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#newPreviewUrl').textContent)">Copiar</button></div></div><div class="field"><label>LINK P\u00daBLICO DEFINITIVO</label><div class="copyline"><code id="newPublicUrl">${esc(data.public_url)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#newPublicUrl').textContent)">Copiar</button></div></div><button class="btn wide" onclick="libriCloseModal();libriAdminPage()">Concluir</button></div>`)}catch(err){console.error(err);btn.disabled=false;btn.textContent='Criar evento';libriToast('Erro inesperado ao criar o evento.')}}
async function openAdminEvent(id){const key=sessionStorage.getItem('libriAdminKey'),{r,data}=await api(`/api/admin/events/${id}`,{headers:{'x-admin-key':key}});if(!r.ok)return libriToast(data.message||'Erro ao abrir.');const e=data.event;libriModal(`<div class="modal-head"><div><div class="kicker">IDENTIDADE LIBRI</div><h2>${esc(e.event_name)}</h2><span class="badge ${statusBadge(e.display_status)}">${statusLabel(e.display_status)}</span></div><button class="close" onclick="libriCloseModal()">\u00d7</button></div><div class="preview-box" style="margin-top:14px">${e.preview_url?`<img src="${attr(e.preview_url)}" alt="">`:''}<div class="caption"><small>Preview 16:9 para WhatsApp</small><br><strong>${esc(e.event_name)}</strong></div></div><div class="field" style="margin-top:10px"><label>ENVIAR / TROCAR PREVIEW</label><input id="adminPreview" type="file" accept="image/jpeg,image/png,image/webp"><span id="adminPreviewInfo" class="small muted">A imagem ser\u00e1 comprimida antes do upload.</span></div><div class="form-grid" style="margin-top:10px"><div class="field full"><label>T\u00cdTULO EDITORIAL</label><input id="adTitle" value="${attr(e.public_title||'')}"></div><div class="field full"><label>MENSAGEM INICIAL</label><textarea id="adIntro">${esc(e.intro||'')}</textarea></div><div class="field"><label>ESTILO</label><select id="adStyle"><option value="home" ${e.experience_style==='home'?'selected':''}>Nosso Lar</option><option value="journey" ${e.experience_style==='journey'?'selected':''}>Nossa Jornada</option><option value="classic" ${e.experience_style==='classic'?'selected':''}>Cl\u00e1ssica</option></select></div><div class="field"><label>PRINCIPAL</label><input id="adPrimary" type="color" value="${attr(e.primary_color)}"></div><div class="field"><label>SECUND\u00c1RIA</label><input id="adSecondary" type="color" value="${attr(e.secondary_color)}"></div><div class="field"><label>ACENTO</label><input id="adAccent" type="color" value="${attr(e.accent_color)}"></div></div><div class="actions" style="margin-top:12px"><button class="btn" onclick="saveAdminEvent(${js(id)})">Salvar identidade</button><a class="btn secondary" href="${attr(e.private_preview_url)}" target="_blank"><i class="ti ti-eye"></i> Abrir pr\u00e9via</a><button class="btn secondary" onclick="regenClientAccess(${js(id)})">Novo acesso da cliente</button></div><div id="newAccess"></div>`);document.querySelector('#adminPreview').addEventListener('change',async ev=>{if(!ev.target.files[0])return;try{pendingPreview=await compressImage(ev.target.files[0],1280,180000,.86);document.querySelector('#adminPreviewInfo').textContent=`Preview otimizado para ${Math.round(pendingPreview.size/1024)} KB.`}catch{libriToast('N\u00e3o foi poss\u00edvel processar essa imagem.')}})}
async function saveAdminEvent(id){const key=sessionStorage.getItem('libriAdminKey'),body={public_title:document.querySelector('#adTitle').value.trim(),intro:document.querySelector('#adIntro').value.trim(),experience_style:document.querySelector('#adStyle').value,primary_color:document.querySelector('#adPrimary').value,secondary_color:document.querySelector('#adSecondary').value,accent_color:document.querySelector('#adAccent').value};let x=await api(`/api/admin/events/${id}`,{method:'PATCH',headers:{'content-type':'application/json','x-admin-key':key},body:JSON.stringify(body)});if(!x.r.ok)return libriToast(x.data.message||'Erro ao salvar.');if(pendingPreview){const up=await fetch(`/api/admin/events/${id}/preview`,{method:'PUT',headers:{'x-admin-key':key,'content-type':'image/webp'},body:pendingPreview});if(!up.ok)return libriToast('Identidade salva, mas o preview n\u00e3o subiu.');pendingPreview=null}libriToast('Identidade salva \u2713');libriCloseModal();libriAdminPage()}
async function regenClientAccess(id){if(!confirm('Gerar um novo acesso invalida o link anterior da cliente. Continuar?'))return;const key=sessionStorage.getItem('libriAdminKey'),{r,data}=await api(`/api/admin/events/${id}/access`,{method:'POST',headers:{'x-admin-key':key}});if(!r.ok)return libriToast(data.message||'Erro.');document.querySelector('#newAccess').innerHTML=`<div class="field" style="margin-top:12px"><label>NOVO ACESSO DA CLIENTE</label><div class="copyline"><code id="regenUrl">${esc(data.client_url)}</code><button class="btn secondary small" onclick="copyText(document.querySelector('#regenUrl').textContent)">Copiar</button></div></div>`}

/* COMMON UI */
function libriModal(html){modalRoot.innerHTML=`<div class="modal-back" onclick="if(event.target===this)libriCloseModal()"><div class="modal">${html}</div></div>`}
function libriCloseModal(){modalRoot.innerHTML='';pendingGiftPhoto=null;pendingPreview=null}
async function copyText(t){try{await navigator.clipboard.writeText(t);libriToast('Copiado \u2713')}catch{libriToast('N\u00e3o foi poss\u00edvel copiar.')}}
function renderQr(id,text){const el=document.getElementById(id);if(!el)return;if(typeof qrcode!=='function'){el.innerHTML='<span class="small muted">QR indispon\u00edvel. Use o bot\u00e3o copiar.</span>';return}try{const qr=qrcode(0,'M');qr.addData(text);qr.make();const n=qr.getModuleCount(),quiet=4,size=216,modules=n+quiet*2,cell=size/modules,canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;canvas.setAttribute('aria-label','QR Code');const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,size,size);ctx.fillStyle='#000';for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(qr.isDark(r,c)){const x=Math.floor((c+quiet)*cell),y=Math.floor((r+quiet)*cell),x2=Math.ceil((c+quiet+1)*cell),y2=Math.ceil((r+quiet+1)*cell);ctx.fillRect(x,y,x2-x,y2-y)}el.innerHTML='';el.appendChild(canvas)}catch(e){console.error(e);el.innerHTML='<span class="small muted">N\u00e3o foi poss\u00edvel gerar o QR.</span>'}}
async function compressImage(file,maxSide,targetBytes,startQuality=.82){const img=await fileToImage(file),scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),w=Math.max(1,Math.round(img.naturalWidth*scale)),h=Math.max(1,Math.round(img.naturalHeight*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{alpha:false});ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.drawImage(img,0,0,w,h);let q=startQuality,blob;do{blob=await new Promise(r=>canvas.toBlob(r,'image/webp',q));q-=.07}while(blob&&blob.size>targetBytes&&q>.3);if(!blob)throw new Error('compression_failed');return blob}
function fileToImage(file){return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('image_load_failed'))};img.src=url})}

/* PIX BR CODE */
function buildPix(key,name,city,amount){const gui=emv('00','BR.GOV.BCB.PIX')+emv('01',String(key).trim()),merchant=emv('26',gui),value=Number(amount).toFixed(2),payload=emv('00','01')+merchant+emv('52','0000')+emv('53','986')+emv('54',value)+emv('58','BR')+emv('59',pixText(name,25))+emv('60',pixText(city,15))+emv('62',emv('05','***'))+'6304';return payload+crc16(payload)}
function emv(id,value){const v=String(value);return id+String(v.length).padStart(2,'0')+v}
function pixText(v,max){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9 $%*+\-./:]/g,'').toUpperCase().slice(0,max)||'NAO INFORMADO'}
function crc16(str){let crc=0xFFFF;for(let c=0;c<str.length;c++){crc^=str.charCodeAt(c)<<8;for(let i=0;i<8;i++){crc=(crc&0x8000)?((crc<<1)^0x1021):(crc<<1);crc&=0xFFFF}}return crc.toString(16).toUpperCase().padStart(4,'0')}